#!/usr/bin/env node
/*
 * Generates the Woodfish Neovim colorschemes from the theme-core palettes, the VS Code theme files and
 * the colors VS Code gives the sample code (see lib/targets.mjs).
 *
 *   node scripts/generate.mjs          write colors/ and lua/
 *   node scripts/generate.mjs --check  fail if generated files are stale
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createShiki, loadCaptures, themeTargets } from './lib/targets.mjs';
import { FONT_STYLES, ROOT, WOODFISH_PALETTES, opaqueHex, parseJsonc, themeFile } from './lib/shared.mjs';

const PALETTE_FILE = 'lua/woodfish/palettes.lua';
const LUALINE_FILE = 'lua/lualine/themes/woodfish.lua';
const HEADER = '-- Generated by apps/neovim/scripts/generate.mjs; do not edit by hand.\n';

const DEFAULT_EDITOR_COLORS = {
  dark: {
    'editorLineNumber.foreground': '#858889',
    'editor.lineHighlightBackground': '#242526',
    'editor.selectionBackground': '#276782DD',
    'editorCursor.foreground': '#BBBEBF',
    'editorWidget.background': '#202122',
    'editorSuggestWidget.background': '#202122',
    'editorError.foreground': '#F14C4C',
    'editorWarning.foreground': '#CCA700',
    'editor.findMatchBackground': '#27678290',
  },
  light: {
    'editorLineNumber.foreground': '#606060',
    'editor.lineHighlightBackground': '#EAEAEA40',
    'editor.selectionBackground': '#0069CC40',
    'editorCursor.foreground': '#202020',
    'editorWidget.background': '#FAFAFD',
    'editorSuggestWidget.background': '#FAFAFD',
    'editorError.foreground': '#E51400',
    'editorWarning.foreground': '#BF8800',
    'editor.findMatchBackground': '#0069CC40',
  },
};

function hostColors(palette) {
  const theme = parseJsonc(fs.readFileSync(themeFile(palette.slug), 'utf8'));
  const colors = theme.colors || {};
  return Object.fromEntries(
    Object.entries(DEFAULT_EDITOR_COLORS[palette.type]).map(([key, value]) => [key, opaqueHex(colors[key] || value, palette.ui.bg)])
  );
}

/** `capture = "#RRGGBB"`, or `capture = { fg = "#RRGGBB", italic = true, ... }` when VS Code styles the text. */
function luaLanguages(language) {
  return Object.fromEntries(
    Object.entries(language).map(([parser, captures]) => [
      parser,
      Object.fromEntries(
        Object.entries(captures).map(([capture, { fg, style }]) => {
          const attributes = FONT_STYLES.filter(([bit]) => style & bit).map(([, name]) => [name, true]);
          return [capture, attributes.length ? { fg, ...Object.fromEntries(attributes) } : fg];
        })
      ),
    ])
  );
}

export async function selectedPalettes() {
  const highlighter = await createShiki();
  const captures = loadCaptures();
  const palettes = [];
  for (const palette of WOODFISH_PALETTES) {
    const normalize = (colors) => Object.fromEntries(Object.entries(colors).map(([key, value]) => [key, opaqueHex(value, palette.ui.bg)]));
    palettes.push({
      ...palette,
      ui: normalize(palette.ui),
      tokens: normalize(palette.tokens),
      ansi: palette.ansi.map((color) => opaqueHex(color, palette.ui.bg)),
      host: hostColors(palette),
      language: luaLanguages((await themeTargets(highlighter, palette.slug, captures)).language),
    });
  }
  return palettes;
}

const LUA_KEYWORDS = new Set('and break do else elseif end false for function goto if in local nil not or repeat return then true until while'.split(' '));

function lua(value, depth = 0) {
  if (Array.isArray(value)) return `{ ${value.map((child) => lua(child, depth)).join(', ')} }`;
  if (value && typeof value === 'object') {
    const entriesOf = Object.entries(value);
    const key = (name) => (/^[A-Za-z_]\w*$/.test(name) && !LUA_KEYWORDS.has(name) ? name : `[${JSON.stringify(name)}]`);
    if (entriesOf.length <= 4 && entriesOf.every(([, child]) => typeof child !== 'object' || child === null)) {
      return `{ ${entriesOf.map(([name, child]) => `${key(name)} = ${lua(child, depth)}`).join(', ')} }`;
    }
    const pad = '  '.repeat(depth + 1);
    const entries = entriesOf.map(([name, child]) => `${pad}${key(name)} = ${lua(child, depth + 1)},`);
    return `{\n${entries.join('\n')}\n${'  '.repeat(depth)}}`;
  }
  if (typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (value === null) return 'nil';
  return String(value);
}

function renderPalettes(palettes) {
  const data = Object.fromEntries(palettes.map((palette) => [`woodfish-${palette.slug}`, palette]));
  return `${HEADER}return ${lua(data)}\n`;
}

function renderColorscheme(palette) {
  return `${HEADER}require("woodfish").load(${JSON.stringify(`woodfish-${palette.slug}`)})\n`;
}

function renderLualine() {
  return `${HEADER}local woodfish = require("woodfish")
local palette = woodfish.palette()
local ui = palette.ui

local function mode(fg, bg)
  return { fg = fg, bg = bg, gui = "bold" }
end

return {
  normal = { a = mode(ui.accentFg, ui.accent), b = mode(ui.fg, ui.bgWidget), c = mode(ui.fgMuted, ui.bgAlt) },
  insert = { a = mode(ui.accentFg, ui.success), b = mode(ui.fg, ui.bgWidget), c = mode(ui.fgMuted, ui.bgAlt) },
  visual = { a = mode(ui.accentFg, ui.accent2), b = mode(ui.fg, ui.bgWidget), c = mode(ui.fgMuted, ui.bgAlt) },
  replace = { a = mode(ui.accentFg, ui.error), b = mode(ui.fg, ui.bgWidget), c = mode(ui.fgMuted, ui.bgAlt) },
  command = { a = mode(ui.accentFg, ui.warning), b = mode(ui.fg, ui.bgWidget), c = mode(ui.fgMuted, ui.bgAlt) },
  inactive = { a = mode(ui.fgSubtle, ui.bgAlt), b = mode(ui.fgSubtle, ui.bgAlt), c = mode(ui.fgSubtle, ui.bgAlt) },
}
`;
}

export async function generatedFiles() {
  const palettes = await selectedPalettes();
  return new Map([
    [PALETTE_FILE, renderPalettes(palettes)],
    [LUALINE_FILE, renderLualine()],
    ...palettes.map((palette) => [`colors/woodfish-${palette.slug}.lua`, renderColorscheme(palette)]),
  ]);
}

export const normalize = (text) => text.replace(/\r\n/g, '\n');
export const isStale = (actual, expected) => normalize(actual) !== expected;

/** Writes (or, with `check`, verifies) the generated files below `base`. Keys of `generatedFiles` are relative paths. */
export async function run(check, base = ROOT) {
  const files = await generatedFiles();
  for (const [relative, expected] of files) {
    const file = path.join(base, relative);
    if (check) {
      const actual = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
      if (isStale(actual, expected)) throw new Error(`${relative} is stale; run pnpm nvim:generate`);
      continue;
    }
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, expected);
  }
  console.log(check ? '✓ Neovim generated files are up to date' : `✓ generated ${files.size} Neovim files`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  run(process.argv.includes('--check')).catch((error) => {
    console.error(error.message);
    process.exit(1);
  });
}
